eon as (select id from organizations where name='EON'),
v as (
 select v.id, v.sku, v.price_cents, v.weight_grams::float8 g0, p.status, p.etsy_listing_id, p.title,
   (v.sku ~ '^(EON-(WILLW|TWNRL|FMLGRN|STRRID|COMET|LAURX|CADNC|CTAIL|CRGRN|SATFAC|FACMIL|QS26|MERID|HL01)|RSG-BR)') fam,
   coalesce((regexp_match(v.sku,'-R-(10|14|18)\d{2}-'))[1], (regexp_match(v.sku,'-(10|14|18)-\d{2}-\d{3}$'))[1], (regexp_match(v.properties->>'Karat','(10|14|18)'))[1], (regexp_match(p.title,'(10|14|18)[kK]'))[1])::int k,
   (regexp_match(coalesce(case when jsonb_typeof(v.properties)='array' then jsonb_path_query_first(v.properties,'$[*] ? (@.property_name == "Width").values[0]')#>>'{}' else v.properties->>'Width' end,''),'([0-9.]+)'))[1]::float8 w,
   (regexp_match(coalesce(case when jsonb_typeof(v.properties)='array' then jsonb_path_query_first(v.properties,'$[*] ? (@.property_name == "Ring Size").values[0]')#>>'{}' else v.properties->>'Ring Size' end,''),'([0-9.]+)'))[1]::float8 sz
 from product_variants v join products p on p.id=v.product_id
 where p.org_id=(select id from eon) and v.active and p.etsy_deleted_at is null and coalesce(v.sku,'')<>'EON-SIZER-FIT10'),
c as (
 select v.*, case k when 10 then 0.417 when 14 then 0.585 when 18 then 0.75 end pur,
   case when coalesce(g0,0)>0 then g0 else (select gt.g*1.15 from gt where gt.k=v.k and gt.w=round(v.w) and gt.s=least(16,greatest(4,ceil(v.sz)))) end g,
   (coalesce(g0,0)<=0) g_from_table
 from v),
l as (
 select c.*, case when fam then (c.g+1)*(4286.2/31.1034768)*c.pur*1.08 + 130 + 30
                  else c.g*(4286.2/31.1034768)*c.pur*1.07 + 74 + 30 end landed
 from c where coalesce(c.g,0)>0 and c.pur is not null),
f as (select l.*, (ceil(((landed+0.45)/0.88/0.70)/5)*500)::int floor_cents from l)
select count(*) filter (where price_cents<floor_cents) hedef,
 md5(string_agg(case when price_cents<floor_cents then id::text||'|'||price_cents||'>'||floor_cents end, E'\n' order by id)) muhur
from f;

